using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Application.Approvals;using OrcaFacil.Domain.Entities;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.Approvals;
[Authorize(Policy="Permission:Approvals.View")]
public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current,IAuditService audit,ApprovalWorkflowService workflow):PageModel
{public IReadOnlyList<ApprovalRequest> Requests{get;private set;}=[];[BindProperty(SupportsGet=true)]public ApprovalStatus? Status{get;set;}=ApprovalStatus.Pending;public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid a)return Forbid();var query=db.ApprovalRequests.AsNoTracking().Where(x=>x.AccountId==a&&!x.IsDeleted);if(Status.HasValue)query=query.Where(x=>x.Status==Status);Requests=await query.OrderByDescending(x=>x.RequestedAt).ToListAsync(ct);return Page();}public async Task<IActionResult>OnPostApproveAsync(Guid id,CancellationToken ct){if(!await current.HasPermissionAsync("Approvals.Decide",ct)||current.AccountId is not Guid a)return Forbid();var request=await db.ApprovalRequests.SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==a&&!x.IsDeleted,ct);if(request is null)return NotFound();workflow.Approve(request,current.UserId);var document=await db.Documents.SingleAsync(x=>x.Id==request.DocumentId&&x.AccountId==a,ct);document.InternalApprovalStatus=ApprovalStatus.Approved;db.ApprovalRequestEvents.Add(new ApprovalRequestEvent{AccountId=a,ApprovalRequestId=id,ActorUserId=current.UserId,Type=ApprovalEventType.Approved});await audit.RegisterAsync(current.UserId,"approval.approved",nameof(ApprovalRequest),id.ToString(),null,new{request.DocumentId},null,ct,a);await db.SaveChangesAsync(ct);return RedirectToPage();}public async Task<IActionResult>OnPostRejectAsync(Guid id,string reason,CancellationToken ct){if(!await current.HasPermissionAsync("Approvals.Decide",ct)||current.AccountId is not Guid a)return Forbid();var request=await db.ApprovalRequests.SingleOrDefaultAsync(x=>x.Id==id&&x.AccountId==a&&!x.IsDeleted,ct);if(request is null)return NotFound();try{workflow.Reject(request,current.UserId,reason);}catch(ArgumentException ex){TempData["Error"]=ex.Message;return RedirectToPage();}var document=await db.Documents.SingleAsync(x=>x.Id==request.DocumentId&&x.AccountId==a,ct);document.InternalApprovalStatus=ApprovalStatus.Rejected;db.ApprovalRequestEvents.Add(new ApprovalRequestEvent{AccountId=a,ApprovalRequestId=id,ActorUserId=current.UserId,Type=ApprovalEventType.Rejected,Comment=reason.Trim()});await audit.RegisterAsync(current.UserId,"approval.rejected",nameof(ApprovalRequest),id.ToString(),null,new{request.DocumentId,Reason=reason.Trim()},null,ct,a);await db.SaveChangesAsync(ct);return RedirectToPage();}}
